import numpy as np
import pandas as pd
from scipy.optimize import curve_fit

DATA = 'spectrum.csv'


def load():
    return pd.read_csv(DATA)


def pv(x, c, h, w, eta):
    """Pseudo-Voigt, height h, FWHM w, eta = Lorentzian fraction."""
    s = w / 2.3548
    g = np.exp(-0.5 * ((x - c) / s) ** 2)
    l = 1.0 / (1.0 + ((x - c) / (w / 2)) ** 2)
    return h * (eta * l + (1 - eta) * g)


def model_factory(n_peaks, deg=1):
    def f(x, *p):
        y = np.zeros_like(x)
        for k in range(deg + 1):
            y += p[k] * (x - 300.0) ** k
        q = p[deg + 1:]
        for i in range(n_peaks):
            c, h, w, eta = q[4 * i:4 * i + 4]
            y += pv(x, c, h, w, eta)
        return y
    return f


def fit(x, y, p0, lo, hi, deg=1, sigma=None):
    f = model_factory(len(p0) // 4, deg)
    popt, pcov = curve_fit(f, x, y, p0=p0, bounds=(lo, hi), sigma=sigma, absolute_sigma=sigma is not None, maxfev=40000)
    resid = y - f(x, *popt)
    return popt, np.sqrt(np.diag(pcov)), resid, f

